// Band Chart — Basic, route: jsx
// Source: band-chart_2
//
// Self-contained: every local import is inlined below. Requires only d3, react.
// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import { useMemo, useId } from 'react';
import * as d3 from 'd3';

// ---- inlined from Axis ----
type Tick = { value: string; offset: number };

function AxisBottom({
  ticks,
  height,
  width
}: {
  ticks: Tick[];
  height: number;
  width: number;
}) {
  return (
    <g className="axis" transform={`translate(0,${height})`}>
      <line x1={0} x2={width} y1={0} y2={0} />
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(${offset},0)`}>
          <line y1={0} y2={5} />
          <text y={18} textAnchor="middle">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

function AxisLeft({ ticks, width }: { ticks: Tick[]; width: number }) {
  return (
    <g className="axis">
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(0,${offset})`}>
          <line className="grid" x1={0} x2={width} y1={0} y2={0} />
          <text x={-10} dy="0.32em" textAnchor="end">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

const MARGIN = { top: 24, right: 20, bottom: 36, left: 52 };
const DAYS = 365;

/** A low and a high per date; the band is drawn between them. */
export type Data = { date: Date; low: number; high: number }[];

/** Seeded Lehmer generator, not Math.random, so the series survives hot reloads unchanged. */
function temperatureSeries(count: number): Data {
  let seed = 20240101;
  const jitter = (scale: number) => {
    seed = (seed * 16807) % 2147483647;
    return (seed / 2147483647 - 0.5) * scale;
  };
  return Array.from({ length: count }, (_, i) => {
    const phase = (2 * Math.PI * i) / DAYS;
    const mean = 57 + 9 * Math.sin(phase - 1.9) + jitter(7);
    // The daily spread swings seasonally too, so band thickness carries its own signal.
    const spread = 15 + 7 * Math.sin(phase - 2.4) + jitter(4);
    return { date: new Date(2024, 0, 1 + i), low: mean - spread / 2, high: mean + spread / 2 };
  });
}

const DEMO: Data = temperatureSeries(DAYS);

export default function BandChart({ data = DEMO, width }: { data?: Data; width: number }) {
  const gradientId = useId();
  const height = Math.round(width * 0.5);
  const innerWidth = width - MARGIN.left - MARGIN.right;
  const innerHeight = height - MARGIN.top - MARGIN.bottom;

  const x = useMemo(
    () =>
      d3
        .scaleUtc()
        .domain(d3.extent(data, (d) => d.date) as [Date, Date])
        .range([0, innerWidth]),
    [data, innerWidth]
  );

  const y = useMemo(
    () =>
      d3
        .scaleLinear()
        .domain([d3.min(data, (d) => d.low) ?? 0, d3.max(data, (d) => d.high) ?? 0])
        .nice(10)
        .range([innerHeight, 0]),
    [data, innerHeight]
  );

  const band = useMemo(
    () =>
      d3
        .area<Data[number]>()
        .curve(d3.curveStep)
        .x((d) => x(d.date))
        .y0((d) => y(d.low))
        .y1((d) => y(d.high))(data) ?? '',
    [data, x, y]
  );

  const xTicks: Tick[] = useMemo(
    // Capped at 12 so ticks stay monthly and the "%b" labels never repeat.
    () => x.ticks(Math.min(12, Math.max(2, Math.round(innerWidth / 80)))).map((v) => ({
      value: d3.utcFormat('%b')(v),
      offset: x(v)
    })),
    [x, innerWidth]
  );

  const yTicks: Tick[] = useMemo(
    () => y.ticks(5).map((v) => ({ value: String(v), offset: y(v) })),
    [y]
  );

  if (width === 0) return null;

  return (
    <svg viewBox={`0 0 ${width} ${height}`} width="100%" height={height} role="img"
         aria-label="Band chart of daily low and high temperatures over one year">
      <defs>
        <linearGradient id={gradientId} x1="0" x2="0" y1="0" y2="1">
          <stop offset="0%" stopColor="var(--accent)" stopOpacity={0.75} />
          <stop offset="100%" stopColor="var(--accent)" stopOpacity={0.35} />
        </linearGradient>
      </defs>
      <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
        <AxisLeft ticks={yTicks} width={innerWidth} />
        <AxisBottom ticks={xTicks} height={innerHeight} width={innerWidth} />
        <path d={band} fill={`url(#${gradientId})`} />
        <text x={-MARGIN.left} y={-10} fill="var(--muted)" fontSize={11} textAnchor="start">
          ↑ Temperature (°F)
        </text>
      </g>
    </svg>
  );
}
